                  setActivePlateId(plate.id);
                  if (window.innerWidth < 1536) setIsSidebarOpen(false);
                }}
                className={`p-3 rounded-xl cursor-pointer border transition-all ${activePlateId === plate.id ? 'border-blue-500 bg-blue-50 shadow-md ring-2 ring-blue-100' : 'border-gray-200 hover:border-blue-300 hover:bg-gray-50'}`}
              >
                <div className="flex justify-between items-start mb-1">
                  <div className="font-bold text-gray-800 text-xs">Konfiguracja #{index + 1}</div>
                  <div className="bg-white border text-blue-600 text-[10px] px-2 py-0.5 rounded-full font-bold shadow-sm">{plate.quantity} szt.</div>
                </div>
                <div className="text-[11px] text-gray-500 truncate font-mono">Projekt: {plate.projectNumber}</div>
                <div className="text-[11px] text-gray-600 truncate mt-1 font-semibold">{plate.customerName || 'Brak nazwy'}</div>
              </div>
            ))}
          </div>
        </aside>

        {isSidebarOpen && <div className="fixed inset-0 bg-black/20 backdrop-blur-sm z-30 2xl:hidden" onClick={() => setIsSidebarOpen(false)} />}

        <div className="flex-1 flex overflow-hidden no-print">
          {/* Preview Panel - Now on the LEFT */}
          <section 
            ref={previewContainerRef}
            className={`
              ${mobileTab === 'preview' ? 'flex' : 'hidden lg:flex'}
              bg-gray-200/50 flex flex-col border-r border-gray-200 overflow-hidden
            `}
            style={{ width: window.innerWidth >= 1024 ? `${leftPanelWidth}%` : '100%' }}
          >
            <div className="p-3 flex justify-between items-center bg-white border-b shadow-sm shrink-0">
              <div className="flex items-center gap-2">
                 <h3 className="text-gray-700 font-bold flex items-center gap-2 text-xs uppercase tracking-wider">
                  <FileText size={16} className="text-blue-500" /> Podgląd wydruku
                </h3>
              </div>
              <div className="flex bg-gray-100 rounded-lg p-1">
                 <button 
                  onClick={() => setViewMode('single')}
                  className={`flex items-center gap-1 px-3 py-1.5 rounded-md text-[11px] font-bold transition-all ${viewMode === 'single' ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
                 >
                   <Layers size={14} /> Pojedyncza
                 </button>
                 <button 
                  onClick={() => setViewMode('sheet')}
                  className={`flex items-center gap-1 px-3 py-1.5 rounded-md text-[11px] font-bold transition-all ${viewMode === 'sheet' ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
                 >
                   <Sheet size={14} /> Arkusze A4
                 </button>
              </div>
            </div>

            <div className="flex-1 overflow-auto p-4 md:p-6 flex justify-center items-start bg-slate-200/30">
               {viewMode === 'single' ? (
                  <div 
                    className="bg-white shadow-2xl origin-top p-0 rounded-sm transition-transform duration-200"
                    style={{ transform: `scale(${previewScale})` }}
                  >
                     {activePlate && <PlatePreview data={activePlate} />}
                  </div>
                ) : (
                  <div 
                    className="flex flex-col gap-8 origin-top transition-transform duration-200"
                    style={{ transform: `scale(${previewScale * 0.7})` }}
                  >
                    {pages.map((pagePlates, pageIdx) => (
                      <div 
                        key={pageIdx} 
                        className="bg-white shadow-2xl relative flex flex-col items-center"
                        style={{ width: '210mm', height: '297mm', padding: '10mm' }}
                      >
                         <div className="absolute top-4 left-4 text-gray-200 font-black text-6xl select-none pointer-events-none">A4 - {pageIdx + 1}</div>
                         {pagePlates.map((plate, idx) => (
                           <div key={`${plate.id}-${idx}`} className="mb-[5mm]">
                             <PlatePreview data={plate} />
                           </div>
                         ))}
                      </div>
                    ))}
                    {pages.length === 0 && <div className="text-gray-500 bg-white p-8 rounded-xl shadow border">Brak elementów do wydruku.</div>}
                  </div>
                )}
            </div>
            <div className="p-2 text-center text-[10px] text-gray-400 border-t bg-white italic">
              {viewMode === 'single' ? `Skala: ${Math.round(previewScale * 100)}%` : `Arkusz: ${pages.length} str.`}
            </div>
          </section>

          {/* Resizer Handle */}
          <div 
            onMouseDown={startResizing}
            className="hidden lg:flex w-1 bg-gray-300 hover:bg-blue-400 cursor-col-resize items-center justify-center group transition-colors no-print"
          >
            <div className="w-4 h-12 bg-gray-200 border rounded-full flex items-center justify-center group-hover:bg-blue-100 group-hover:border-blue-300 shadow-sm">
               <GripVertical size={14} className="text-gray-400 group-hover:text-blue-500" />
            </div>
          </div>

          {/* Editor Panel - Now on the RIGHT */}
          <section className={`
            ${mobileTab === 'editor' ? 'flex' : 'hidden lg:flex'}
            flex-1 bg-gray-100 p-3 md:p-6 lg:p-8 overflow-y-auto
          `}>
            <div className="max-w-3xl mx-auto w-full">
              {activePlate && (
                <PlateEditor 
                  data={activePlate} 
                  onChange={updateActivePlate}
                  onDuplicate={() => duplicatePlate(activePlate)}
                  onRemove={() => removePlate(activePlate.id)}
                />
              )}
            </div>
          </section>
        </div>

        {/* Print only section */}
        <div className="hidden print:block w-full overflow-visible bg-white">
           {pages.map((pagePlates, pageIdx) => (
             <div key={pageIdx} className={`w-full flex flex-col items-center bg-white ${pageIdx < pages.length - 1 ? 'page-break' : ''}`} style={{ paddingBottom: '20mm' }}>
                {pagePlates.map((plate, plateIdx) => (
                  <div key={`${plate.id}-${pageIdx}-${plateIdx}`} className="w-full flex justify-center mb-8 last:mb-0">
                    <PlatePreview data={plate} />
                  </div>
                ))}
             </div>
           ))}
        </div>
      </main>

      <GlobalEditorModal 
        isOpen={isGlobalEditorOpen}
        onClose={() => setIsGlobalEditorOpen(false)}
        currentTemplate={activePlate}
        onApply={applyGlobalUpdates}
      />
    </div>
  );
};

export default App;
